mapper.select:
SELECT ci.checklist_item_id, ci.performance_project_id, ci.performance_round_id, ci.team_id, t.name AS team_name, ci.scope_code, ci.content, ci.is_required, ci.display_order, ci.is_completed, ci.completed_by_member_id, completed_member.name AS completed_by_member_name, ci.completed_dttm FROM checklist_item ci JOIN team t ON t.team_id = ci.team_id LEFT JOIN member completed_member ON completed_member.member_id = ci.completed_by_member_id WHERE AND ci.performance_project_id = #{performanceProjectId}
AND ci.performance_round_id = #{performanceRoundId}
AND ci.team_id = #{teamId}
AND ci.scope_code = #{scope}
ORDER BY FIELD(ci.scope_code, 'PROJECT', 'ROUND'), ci.performance_round_id, t.name, ci.display_order, ci.checklist_item_id

mapper.update:
UPDATE checklist_item
SET deleted_dttm = #{deletedDttm},
    updated_by_member_id = #{actorMemberId}
WHERE checklist_item_id = #{checklistItemId}
  AND deleted_dttm IS NULL

mapper.insert:
INSERT INTO checklist_item_history (
    checklist_item_id, previous_completed,
    new_completed, changed_by_member_id,
    changed_dttm, reason
) VALUES (
    #{checklistItemId}, #{previousCompleted},
    #{newCompleted}, #{changedByMemberId},
    #{changedDttm}, #{reason}
)
